const SYNC_OBSERVE_MS       = 3;       // Zone 1: observe only
const SYNC_FREQ_TINY_MS     = 8;       // Zone 2: tiny frequency correction
const SYNC_FREQ_PI_MS       = 20;      // Zone 3: PI frequency correction
const SYNC_FREQ_PID_MS      = 40;      // Zone 4: PID frequency correction
const SYNC_DECIDE_MS        = 80;      // Zone 5: decide freq vs phase
