    const sep = document.createElement('span');
    sep.className = 'pa-st-sep';
    sep.textContent = ':';
    line.appendChild(sep);
    const dot = document.createElement('span');
    dot.className = 'pa-st-dot';
    line.appendChild(dot);
    const val = document.createElement('span');
    val.className = 'pa-st-val';
    debugOverlay.fields[spec.val] = val;
    if (spec.dot) debugOverlay.dots[spec.val] = dot;
