    if (d.share >= SYNTAX_DOMINANCE_MIN) { _domFailAt = 0; return; }
    const now = performance.now();
    if (!_domFailAt) { _domFailAt = now; return; }       // first miss — confirm
    if (now - _domFailAt < 450 && !fromSettle) return;   // debounce window
    _domFailAt = 0;
    log('INFO', 'Syntax', 'canvas lost the screen (' + Math.round(d.share * 100) +
        '% of the viewport) — folding the overlay system');
