        setSlider(offsetInput, offsetVal, s.audioOffsetMs || 0, (v) => (v >= 0 ? '+' : '') + v);
        setSlider(bassInput, bassValEl, s.bassBoostAmt || 0, (v) => v + '%');
        setSlider(harmInput, harmValEl, s.harmWarmAmt || 0, (v) => v + '%');
